function evidence = f90_xaero02_extract_candidate_evidence(modelPath, outputDir)
%F90_XAERO02_EXTRACT_CANDIDATE_EVIDENCE Current public 10/7/8 route.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end

[sharedRoot, outputRoot] = localRoots;
pathBefore = path;
addpath(sharedRoot, outputRoot, "-begin");
cleanup = onCleanup(@() path(pathBefore)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
assert(isfield(official, "candidate_base_waypoints_m"), ...
    "SimuVerity:XAERO02:WaypointContractMissing", ...
    "candidate_base_waypoints_m is required.");
baseWaypoints = double(official.candidate_base_waypoints_m);
assert(isequal(size(baseWaypoints), [3 4]) && ...
    all(isfinite(baseWaypoints), "all"), ...
    "SimuVerity:XAERO02:WaypointContractInvalid", ...
    "candidate_base_waypoints_m must be a finite real 3-by-4 matrix.");

spec = struct;
spec.schema = "simuverity.formal90-xaero02-evidence.v1";
spec.task_id = "F90-XAERO-02";
spec.scenarios = official.scenarios;
spec.base_waypoints_m = baseWaypoints;
spec.output_contract = localOutputs;
spec.input_builder = @localInputs;
spec.requested_input_builder = @localRequestedInputs;
spec.stop_time = @(~,~) 60.0;
spec.evidence_sample_s = 0.2;
spec.postprocess = @localPostprocess;
spec.static_audit = @localAudit;

evidence = simuverity_run_candidate_evidence(modelPath, outputDir, spec);
evidence.scenarios = localFinalizeScenarios(evidence.scenarios);
evidence.simulate_pass = all([evidence.scenarios.simulation_pass]);
evidence.all_official_evidence_valid = all([evidence.scenarios.valid]);
evidence.all_scenarios_valid = evidence.all_official_evidence_valid;
evidence.scenario_count = numel(evidence.scenarios);
evidence.structure = evidence.static_audit.structure;
evidence.runtime_model_unchanged = evidence.model_closed_without_save && ...
    evidence.sealed_candidate_substantive_modifications == 0 && ...
    evidence.evaluation_model_substantive_modifications == 0;
evidence.evidence_complete = evidence.score_inputs_valid;
evidence.load_update_compile_simulate = evidence.score_inputs_valid;
evidence.evidence_path = "evidence.json";
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end

function rows = localOutputs
names = ["flight_state", "tracking_state", "actuator_state"];
widths = [10, 7, 8];
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for index = 1:numel(names)
    rows(index).name = names(index);
    rows(index).evidence_name = names(index);
    rows(index).width = widths(index);
end
rows(2).event_columns = 7;
end

function inputs = localInputs(scenario, spec)
base = double(spec.base_waypoints_m);
centroid = mean(base, 2);
waypoints = centroid + double(scenario.waypoint_scale) .* (base - centroid);
inputs = struct("xaero02_input", struct( ...
    "waypoints_m", waypoints, ...
    "crosswind_step_mps", double(scenario.crosswind_step_mps), ...
    "initial_airspeed_mps", double(scenario.initial_airspeed_mps)));
end

function requested = localRequestedInputs(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
time = outputs.time_s;
flight = outputs.flight_state;
tracking = outputs.tracking_state;
tracking(:, 7) = round(tracking(:, 7));
actuator = outputs.actuator_state;

row.outputs.flight_state = flight;
row.outputs.tracking_state = tracking;
row.outputs.actuator_state = actuator;
row.canonical_availability = struct( ...
    "flight_state", true(1, 10), ...
    "tracking_state", true(1, 7), ...
    "actuator_state", true(1, 8));
row.canonical_sources = struct( ...
    "flight_state", localDirectSources(10), ...
    "tracking_state", localDirectSources(7), ...
    "actuator_state", localDirectSources(8));

positionStep = diff(flight(:, 1:3), 1, 1);
trackingError = tracking(:, 4:6);
row.metrics = struct( ...
    "position_path_length_m", sum(vecnorm(positionStep, 2, 2)), ...
    "tracking_error_rms_m", sqrt(mean(sum(trackingError.^2, 2))), ...
    "tracking_error_peak_m", max(vecnorm(trackingError, 2, 2)), ...
    "body_rate_rms_radps", sqrt(mean(sum(flight(:, 7:9).^2, 2))), ...
    "airspeed_min_mps", min(flight(:, 10)), ...
    "airspeed_max_mps", max(flight(:, 10)), ...
    "actuator_rms", sqrt(mean(actuator.^2, 1)), ...
    "actuator_dynamic_range", max(actuator, [], 1) - min(actuator, [], 1), ...
    "waypoint_index_dynamic_range", max(tracking(:, 7)) - min(tracking(:, 7)), ...
    "all_finite", all(isfinite([time; flight(:); tracking(:); actuator(:)])));
row.valid = row.output_contract.all_required_pass && numel(time) >= 250 && ...
    row.metrics.all_finite;
end

function rows = localFinalizeScenarios(rows)
flightChannels = [ ...
    "position_x_m", "position_y_m", "position_z_m", ...
    "velocity_x_mps", "velocity_y_mps", "velocity_z_mps", ...
    "body_rate_p_radps", "body_rate_q_radps", "body_rate_r_radps", ...
    "airspeed_mps"];
flightUnits = ["m","m","m","m/s","m/s","m/s", ...
    "rad/s","rad/s","rad/s","m/s"];
trackingChannels = [ ...
    "reference_position_x_m", "reference_position_y_m", ...
    "reference_position_z_m", "tracking_error_x_m", ...
    "tracking_error_y_m", "tracking_error_z_m", ...
    "active_waypoint_index"];
trackingUnits = ["m","m","m","m","m","m","1"];
actuatorChannels = [ ...
    "left_aileron_deflection_rad", "right_aileron_deflection_rad", ...
    "left_elevator_deflection_rad", "right_elevator_deflection_rad", ...
    "rudder_deflection_rad", "horizontal_tail_trim_rad", ...
    "left_motor_angular_speed_radps", "right_motor_angular_speed_radps"];
actuatorUnits = ["rad","rad","rad","rad","rad","rad","rad/s","rad/s"];
for index = 1:numel(rows)
    outputs = rows(index).outputs;
    time = outputs.time_s;
    rows(index).simulate_pass = rows(index).simulation_pass;
    rows(index).input = rows(index).requested_inputs;
    rows(index).logs = struct( ...
        "flight_state", localLog(time, outputs.flight_state, ...
            flightChannels, flightUnits, ...
            rows(index).canonical_availability.flight_state, ...
            rows(index).canonical_sources.flight_state), ...
        "tracking_state", localLog(time, outputs.tracking_state, ...
            trackingChannels, trackingUnits, ...
            rows(index).canonical_availability.tracking_state, ...
            rows(index).canonical_sources.tracking_state), ...
        "actuator_state", localLog(time, outputs.actuator_state, ...
            actuatorChannels, actuatorUnits, ...
            rows(index).canonical_availability.actuator_state, ...
            rows(index).canonical_sources.actuator_state));
end
end

function value = localLog(time, data, channels, units, availability, sources)
value = struct( ...
    "format", "Timeseries", ...
    "channels", channels, ...
    "units", units, ...
    "time", time, ...
    "data", data, ...
    "availability", logical(availability), ...
    "sources", sources);
end

function values = localDirectSources(width)
values = strings(1, width);
for index = 1:width
    values(index) = "public:" + index;
end
end

function audit = localAudit(model, spec)
raw = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = raw.semantic_types;
charts = localChartCount(model);
has = @(tokens) nnz(contains(semantic, tokens)) > 0;
plant = has(["6dof","six-dof","rigid body","quaternion","state-space"]);
controller = has(["pid","controller","stateflow","relay"]);
actuator = has(["actuator","servo","motor","transfer function"]);
aeroPropulsion = has(["aerodynamic","aero","propulsion","propeller","thrust"]);
structure = struct( ...
    "nonlinear_six_dof_plant_qualified", plant || charts >= 1, ...
    "feedback_controller_qualified", controller || charts >= 1, ...
    "dynamic_actuator_path_qualified", actuator || charts >= 2, ...
    "aerodynamic_or_propulsion_path_qualified", aeroPropulsion || charts >= 2, ...
    "closed_signal_cycle_present", raw.signal_cycle_present, ...
    "public_outputs_connected", ...
        raw.connected_output_count == numel(spec.output_contract));
audit = struct( ...
    "dynamic_block_count", raw.dynamic_block_count, ...
    "physical_connection_block_count", raw.physical_connection_block_count, ...
    "executable_chart_count", charts, ...
    "connected_public_output_count", raw.connected_output_count, ...
    "signal_cycle_present", raw.signal_cycle_present, ...
    "structure", structure, ...
    "core_path_qualified", ...
        raw.connected_output_count == numel(spec.output_contract) && ...
        raw.nontrivial_output_source_count == numel(spec.output_contract) && ...
        raw.dynamic_block_count + charts >= 1 && raw.signal_cycle_present);
end

function count = localChartCount(model)
count = 0;
try
    root = sfroot;
    charts = root.find("-isa", "Stateflow.EMChart");
    for index = 1:numel(charts)
        pathValue = string(charts(index).Path);
        if pathValue == model || startsWith(pathValue, model + "/")
            count = count + 1;
        end
    end
catch
end
end

function localWriteJson(pathOut, payload)
fid = fopen(pathOut, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:XAERO02:EvidenceWrite", ...
    "Cannot publish candidate evidence JSON.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(payload, PrettyPrint=true), "char");
fwrite(fid, newline, "char");
end

function [sharedRoot, outputRoot] = localRoots
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for index = 1:3
    repoRoot = fileparts(repoRoot);
end
outputRoot = fullfile(repoRoot, "scripts", "unified", "public_output");
end
